import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tiny early game: cooperate to build trust, but punish an opening D quickly.
    if n <= 2:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    opp_c = 0
    opp_d = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'D':
            my_d += 1
        if me == 'C' and op == 'C':
            cc += 1
        elif me == 'C' and op == 'D':
            cd += 1
        elif me == 'D' and op == 'C':
            dc += 1
        else:
            dd += 1

    last_me, last_op = history[-1]

    # Recent opponent behavior.
    look = 10 if n >= 10 else n
    recent_opp_d = 0
    recent_opp_c = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1
    recent_my_d = 0
    for i in range(n - look, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    # Trailing runs.
    opp_run_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_run_d += 1
        i -= 1

    opp_run_c = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        opp_run_c += 1
        i -= 1

    opp_rate = opp_c / float(n)
    remaining = 100 - n

    # Endgame: exploit heavily once retaliation cannot be repaid.
    if n >= 96:
        if opp_rate > 0.85 and opp_d == 0:
            return 'C'
        return 'D'

    if n >= 88:
        if opp_rate > 0.9 and opp_run_c >= 3:
            return 'C'
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent is overwhelmingly cooperative: extract value but keep them cooperative.
    if n >= 12 and opp_rate >= 0.9 and opp_run_d == 0:
        # Start probing after trust established.
        if n < 60:
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        if n < 85:
            if rng.random() < 0.45:
                return 'D'
            return 'C'
        return 'D'

    # Opponent almost always defects: stop feeding them, defect and only rare probes.
    if n >= 6 and opp_rate <= 0.15:
        if remaining > 10 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Sustained defection streak: punish firmly, but test for recoverability.
    if opp_run_d >= 3:
        if opp_run_d >= 5:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if last_me == 'D' and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent just defected: retaliate, with limited forgiveness only if very cooperative recently.
    if last_op == 'D':
        if opp_rate > 0.75 and recent_opp_d <= 1 and n < 90:
            return 'C'
        # Avoid locking into permanent DD if we have both been defecting.
        if last_me == 'D' and dd >= 3 and rng.random() < 0.2:
            return 'C'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent just cooperated. Decide whether to reciprocate or exploit.
    if opp_rate >= 0.7:
        # High trust: mostly cooperate, occasionally defect to gather extra points.
        if n >= 20 and n < 85 and recent_opp_d == 0:
            if rng.random() < 0.07:
                return 'D'
            return 'C'
        if opp_run_c >= 4 and n >= 30 and n < 85:
            if rng.random() < 0.05:
                return 'D'
            return 'C'
        return 'C'

    if opp_rate >= 0.45:
        # Mixed opponent: cooperate while they cooperate, prefer C to keep CC going.
        if recent_opp_d >= 3:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        if recent_my_d >= 3:
            return 'C'
        return 'C'

    # Opportunistic/mostly-defecting opponent: defect primarily, probe occasionally.
    if opp_rate >= 0.25:
        if n < 85 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if remaining > 12 and rng.random() < 0.12:
        return 'C'
    return 'D'
